// frontend/src/pages/Orders.js

import { useEffect, useState } from "react";
import {
  getOrdersByUser,
  createOrder,
  deleteOrder
} from "../services/api";

export default function Orders({ cart, setCart, user }) {
  const [orders, setOrders] = useState([]);

  // ... (codul existent de încărcare comenzi, checkout etc.)

  return (
    <div>
      {/* ───────────────────────────── PAUSĂ PENTRU ANCORĂ Coș ───────────────────────────── */}
      <div id="cart"></div>

      <h3>Coș</h3>
      {cart.length === 0 ? (
        <p>Coșul este gol.</p>
      ) : (
        cart.map((it, i) => (
          <div key={i}>
            {it.name} x{it.quantity}
          </div>
        ))
      )}
      <button onClick={checkout} disabled={cart.length === 0}>
        Trimite comandă
      </button>

      {/* ───────────────────────────── Restul secțiunii „Comenzi existente” ───────────────────────────── */}
      <h3>Comenzi existente</h3>
      {orders.length === 0 && <p>Nu ai comenzi.</p>}
      {orders.map((o) => (
        <div
          key={o.OrderId}
          style={{ border: "1px solid #ddd", margin: "5px", padding: "5px" }}
        >
          <p>
            ID: {o.OrderId} | Status: {o.Status} | Total: {o.TotalPrice} lei
          </p>
          <p>Items:</p>
          <ul>
            {o.items.map((it) => (
              <li key={it.ItemId}>
                {/** Folosim numele produsului dacă l-ai transmis în momentul 
                     creării comenzii; altfel afișăm ID-ul */}
                Produs {it.ProductId} x{it.Quantity}
              </li>
            ))}
          </ul>
          <button onClick={() => removeOrder(o.OrderId)}>
            Șterge comanda
          </button>
        </div>
      ))}
    </div>
  );
}
